ctx.restore()}
function gainXP(n=1){state.xp+=n;if(state.xp>=state.level*8){state.xp-=state.level*8;state.level++;state.energy=Math.min(100,state.energy+12);toast(`A little wiser. Level ${state.level}!`)}}
function setMeter(id,num,bar,max=100){document.getElementById(id).textContent=Math.round(num)+' / '+max;document.getElementById(bar).style.width=Math.max(0,num/max*100)+'%'}
function renderUI(){document.getElementById('wallet').textContent='◈ '+state.coins;document.getElementById('clock').textContent=`Day ${state.day} · ${String(state.hour).padStart(2,'0')}:${String(state.minute).padStart(2,'0')}`;setMeter('healthNum',state.health,'healthBar');setMeter('hungerNum',state.hunger,'hungerBar');setMeter('energyNum',state.energy,'energyBar');document.getElementById('honor').textContent=state.honor;document.getElementById('rep').textContent=state.rep;document.getElementById('wanted').textContent=state.wanted?'✦'.repeat(state.wanted):'None';document.getElementById('level').textContent=state.level;document.getElementById('jobTitle').textContent=state.job;document.getElementById('conditionText').textContent=state.wanted?'Under suspicion':state.hunger<25?'Famished':state.energy<20?'Exhausted':'Steady';document.getElementById('questCount').textContent=Object.values(state.quests).filter(Boolean).length+' / 3';const q=[];q.push(`<div class="quest-icon">${state.quests.meet?'☑':'①'}</div><div><b>Know your neighbors</b><p>${state.quests.meet?'You’ve made a first impression.':'Greet someone in the commons.'}</p></div>`);q.push(`<div class="quest-icon">${state.quests.forage?'☑':'②'}</div><div><b>Useful things grow wild</b><p>${state.quests.forage?'A few herbs in your satchel.':'Forage for wild herbs.'}</p></div>`);q.push(`<div class="quest-icon">${state.quests.work?'☑':'③'}</div><div><b>Earn an honest coin</b><p>${state.quests.work?'Your first shift is behind you.':'Ask Mara or the guildhall for work.'}</p></div>`);document.getElementById('questList').innerHTML=q.join('');document.getElementById('log').innerHTML=(state.logs.length?state.logs:['A new chapter begins…']).map(x=>`<div>· ${x}</div>`).join('')}
function modal(title,body,options=[]){state.dialogOpen=true;const el=document.getElementById('dialog');el.innerHTML=`<div class="eyebrow">Brackenridge · ${title}</div><h1 style="font-size:30px;margin:8px 0">${title}</h1><div class="dialog-text">${body}</div><div class="dialog-options">${options.map((o,i)=>`<button data-choice="${i}">${o.label}</button>`).join('')}</div><div class="close-row"><button data-close>Leave</button></div>`;document.getElementById('dialogBackdrop').hidden=false;el.querySelectorAll('[data-choice]').forEach((b,i)=>b.onclick=()=>options[i].run());el.querySelector('[data-close]').onclick=closeModal}
function closeModal(){document.getElementById('dialogBackdrop').hidden=true;state.dialogOpen=false}
function itemCount(name){return state.items[name]||0}function addItem(n,c){state.items[n]=(state.items[n]||0)+c}
function meet(p){if(!state.quests.meet){state.quests.meet=true;state.rep++;log('You introduced yourself to the town.');}}
function talkTo(p){meet(p);const rel=state.relationships[p.id]||0;modal(p.name,`${p.greeting}<br><br><span style="color:#d9c477">${p.role}</span> · Your bond: ${rel<0?'Wary':rel>3?'Friendly':rel>0?'Warm':'New acquaintance'}.`,[
{label:'💬 Share a little conversation · free',run:()=>{state.relationships[p.id]=(state.relationships[p.id]||0)+1;state.rep++;state.energy=Math.max(0,state.energy-2);log(`You had a pleasant chat with ${p.name}.`);toast(`${p.name} seems a little more at ease.`);closeModal();renderUI()}},
{label:'🎁 Offer a bread ration · improve your bond',run:()=>{if(itemCount('Bread')<1){toast('You have no bread to share.');return}addItem('Bread',-1);state.relationships[p.id]=(state.relationships[p.id]||0)+2;state.honor++;log(`You shared bread with ${p.name}.`);closeModal();renderUI()}},
{label:'👋 Ask about paid work',run:()=>{if(p.id==='mara')jobAtBakery();else if(p.id==='bryn')jobAtStable();else {modal(p.name,'I hear the Guildhall posts work each morning. Talk to the clerk at the market.',[{label:'Got it',run:closeModal}])}}},
{label:'🃏 Play a small-stakes card hand · 5◈',run:()=>playCards(p)}]);}
function interact(){if(!state.started)return;if(nearby?.type==='person'){talkTo(nearby.obj);return}let b=nearby?.type==='building'?nearby.obj:nearestBuilding();if(!b){toast('Nothing close enough to interact with.');return}if(b.id==='home')homeMenu();else if(b.id==='bakery')bakeryMenu();else if(b.id==='inn')innMenu();else if(b.id==='shop')marketMenu();else if(b.id==='herbalist')herbMenu();else stableMenu()}
function nearestBuilding(){let best=null,d=999;for(const b of buildings){let dd=Math.hypot(state.x-(b.x+b.w/2),state.y-(b.y+b.h+10));if(dd<d){best=b;d=dd}}return d<95?best:null}
function homeMenu(){const title=state.homeLevel?'Your Homestead':'The Old Cottage';modal(title,`Your plot is a little patch of possibility. ${state.homeLevel?'Turnips are coming along, and your cottage feels more like yours.':'The roof is patched with hope. Your plot has rich soil and room to grow.'}<br><br>Wood: ${itemCount('Wood')} · Stone: ${itemCount('Stone')} · Turnips: ${itemCount('Turnip')}`,[
{label:'🌱 Tend the garden · 4 energy',run:()=>{if(state.energy<4){toast('You need a little rest first.');return}state.energy-=4;state.hunger-=3;if(Math.random()<.7){addItem('Turnip',2);state.xp++;state.quests.forage=state.quests.forage||false;log('You tended a row of turnips. Two are ready to harvest.')}else{addItem('Turnip',1);log('You watered the seedlings. One turnip is ready.')}closeModal();renderUI()}},
{label:'🪵 Repair the cottage · 12 wood, 8 stone, 30◈',run:()=>{if(itemCount('Wood')<12||itemCount('Stone')<8||state.coins<30){toast('You need 12 wood, 8 stone, and 30 coins.');return}addItem('Wood',-12);addItem('Stone',-8);state.coins-=30;state.homeLevel++;state.job='Homesteader · Cottage restored';state.rep+=2;state.xp+=3;log('You repaired the cottage. It finally feels like home.');toast('Cottage restored! Sleep is more refreshing.');closeModal();renderUI()}},
{label:'🛏️ Sleep until morning',run:()=>{state.day++;state.hour=7;state.minute=0;state.energy=100;state.health=Math.min(100,state.health+25);state.hunger=Math.max(0,state.hunger-18);state.wanted=Math.max(0,state.wanted-1);state.crimeUntil=0;log(`You woke on day ${state.day}, rested and ready.`);closeModal();renderUI()}},
{label:'📦 Sell your harvest · 4◈ each turnip',run:()=>{let n=itemCount('Turnip');if(!n){toast('No turnips to sell.');return}state.coins+=n*4;state.items.Turnip=0;log(`Sold ${n} turnip${n>1?'s':''} for ${n*4} coins.`);closeModal();renderUI()} }])}
function bakeryMenu(){modal('Mara’s Oven','The bakery smells like cinnamon and early mornings. Mara has one shift open.',[{label:'🥖 Work a bakery shift · earn 12◈, spend 18 energy',run:()=>{if(state.energy<18){toast('You are too tired for a full shift.');return}state.energy-=18;state.hunger-=9;state.coins+=12;state.items.Bread=(state.items.Bread||0)+1;state.quests.work=true;state.job='Bakery hand · Part-time';state.rep++;gainXP(2);log('You kneaded dough and served the morning rush. Earned 12 coins.');toast('Shift complete · +12◈ and a loaf of bread');closeModal();renderUI()}},{label:'Buy a loaf · 5◈',run:()=>{if(state.coins<5){toast('Not enough coins.');return}state.coins-=5;addItem('Bread',1);log('Bought a fresh loaf from Mara.');closeModal();renderUI()}},{label:'Ask about the neighborhood',run:()=>talkTo(people.find(p=>p.id==='mara'))}])}
function marketMenu(){modal('Market & Guildhall','A noticeboard creaks beside the supply stall. There is honest work here—and everything has a price.',[{label:'🪓 Take a guild gathering contract · earn 16◈',run:()=>{if(state.energy<15){toast('You need 15 energy for field work.');return}state.energy-=15;state.hunger-=8;state.coins+=16;addItem('Wood',4);state.quests.work=true;state.job='Guild gatherer · Contract';state.rep++;gainXP(2);log('You gathered timber for the guild and earned 16 coins.');toast('Contract complete · +16◈, +4 wood');closeModal();renderUI()}},{label:'Buy a starter bundle · 18◈ (8 wood, 4 stone)',run:()=>{if(state.coins<18){toast('Not enough coins.');return}state.coins-=18;addItem('Wood',8);addItem('Stone',4);log('Bought a small bundle of building materials.');closeModal();renderUI()}},{label:'Buy a hearty meal · 7◈',run:()=>{if(state.coins<7){toast('Not enough coins.');return}state.coins-=7;state.hunger=Math.min(100,state.hunger+35);state.health=Math.min(100,state.health+8);log('A warm meal put some color back in your cheeks.');closeModal();renderUI()}},{label:'🧥 Buy a town coat · 20◈ (+standing with merchants)',run:()=>{if(state.coins<20){toast('Not enough coins.');return}state.coins-=20;state.rep+=2;state.job='Town coat · Well-presented';log('You bought a fine wool coat. People notice.');closeModal();renderUI()}}])}
