function bakeryMenu(){modal('Mara’s Oven','The bakery smells like cinnamon and early mornings. Mara has one shift open.',[{label:'🥖 Work a bakery shift · earn 12◈, spend 18 energy',run:()=>{if(state.energy<18){toast('You are too tired for a full shift.');return}state.energy-=18;state.hunger-=9;state.coins+=12;addItem('Bread',1);state.quests.work=true;state.job='Bakery hand · Part-time';state.rep++;gainXP(2);log('You kneaded dough and served the morning rush. Earned 12 coins.');toast('Shift complete · +12◈ and a loaf of bread');closeModal();renderUI()}},{label:'Buy a loaf · 5◈',run:()=>{if(state.coins<5){toast('Not enough coins.');return}state.coins-=5;addItem('Bread',1);log('Bought a fresh loaf from Mara.');closeModal();renderUI()}},{label:'Ask about the neighborhood',run:()=>talkTo(people.find(p=>p.id==='mara'))}])}
function jobAtBakery(){closeModal();bakeryMenu()}function jobAtStable(){closeModal();stableMenu()}
function marketMenu(){modal('Market & Guildhall','A noticeboard creaks beside the supply stall. There is honest work here—and everything has a price.',[{label:'🪓 Take a guild gathering contract · earn 16◈',run:()=>{if(state.energy<15){toast('You need 15 energy for field work.');return}state.energy-=15;state.hunger-=8;state.coins+=16;addItem('Wood',4);state.quests.work=true;state.job='Guild gatherer · Contract';state.rep++;gainXP(2);log('You gathered timber for the guild and earned 16 coins.');toast('Contract complete · +16◈, +4 wood');closeModal();renderUI()}},{label:'Buy a starter bundle · 18◈ (8 wood, 4 stone)',run:()=>{if(state.coins<18){toast('Not enough coins.');return}state.coins-=18;addItem('Wood',8);addItem('Stone',4);log('Bought a small bundle of building materials.');closeModal();renderUI()}},{label:'Buy a hearty meal · 7◈',run:()=>{if(state.coins<7){toast('Not enough coins.');return}state.coins-=7;state.hunger=Math.min(100,state.hunger+35);state.health=Math.min(100,state.health+8);log('A warm meal put some color back in your cheeks.');closeModal();renderUI()}},{label:'🧥 Buy a town coat · 20◈ (+standing with merchants)',run:()=>{if(state.coins<20){toast('Not enough coins.');return}state.coins-=20;state.rep+=2;state.job='Town coat · Well-presented';log('You bought a fine wool coat. People notice.');closeModal();renderUI()}},{label:'🫳 Steal from the market stall · risky',run:()=>crime('You slipped a handful of coins from the market till.',8,18)}])}
function herbMenu(){modal('Foxglove Remedies','Tamsin knows the uses of every plant in the valley. She will trade for a few good finds.',[{label:'Buy a tonic · 8◈ (+30 vitality)',run:()=>{if(state.coins<8){toast('Not enough coins.');return}state.coins-=8;state.health=Math.min(100,state.health+30);log('Tamsin’s tonic restored your vitality.');closeModal();renderUI()}},{label:'Trade 2 herbs for 10◈',run:()=>{if(itemCount('Herbs')<2){toast('You need two herbs to trade.');return}addItem('Herbs',-2);state.coins+=10;log('Tamsin bought your herbs.');closeModal();renderUI()}},{label:'Ask Tamsin about wild plants',run:()=>talkTo(people.find(p=>p.id==='tamsin'))}])}
function stableMenu(){modal('Ashford Stables','Bryn has a few chores to catch up on. A faithful companion might be in your future.',[{label:'🐎 Work a stable shift · earn 10◈, spend 14 energy',run:()=>{if(state.energy<14){toast('You are too tired.');return}state.energy-=14;state.hunger-=8;state.coins+=10;state.quests.work=true;state.job='Stablehand · Part-time';gainXP(1);log('You mucked stalls and brushed the horses. Earned 10 coins.');closeModal();renderUI()}},{label:state.pet?'🐕 Visit your companion':'🐕 Adopt a scruffy dog · 25◈',run:()=>{if(state.pet){toast('Your dog is happily waiting at home.');closeModal();return}if(state.coins<25){toast('You need 25 coins to adopt.');return}state.coins-=25;state.pet=true;state.rep++;log('A scruffy little dog has joined your family.');toast('You have a companion!');closeModal();renderUI()}},{label:'Talk with Bryn',run:()=>talkTo(people.find(p=>p.id==='bryn'))}])}
function innMenu(){modal('The Lantern Inn','A fiddle plays softly by the fire. The inn is a safe place to eat, hear rumors, or test your luck.',[{label:'🍲 Eat supper and restore your strength · 6◈',run:()=>{if(state.coins<6){toast('Not enough coins.');return}state.coins-=6;state.hunger=Math.min(100,state.hunger+30);state.energy=Math.min(100,state.energy+12);state.health=Math.min(100,state.health+5);log('Supper and a warm seat restored your spirits.');closeModal();renderUI()}},{label:'🃏 Play cards with Lute · 5◈',run:()=>playCards(people.find(p=>p.id==='lute'))},{label:'🍻 Hear the latest gossip',run:()=>{const rumors=['They say lights have been seen among the old standing stones after midnight.','A trader’s cart is due from the coast before the week turns.','The watch captain is looking for a reliable tracker.','Someone found a silver locket by Foxglove Creek.'];state.rep++;log('You spent the evening listening to the town.');modal('A whisper over cider',rumors[Math.floor(Math.random()*rumors.length)],[{label:'Keep that in mind',run:closeModal}])}},{label:'🫳 Lift a purse in the crowd · very risky',run:()=>crime('You slipped away with a purse from the crowded common room.',12,24)}])}
