let moveTarget=null;canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H),ox=(r.width-W*scale)/2,oy=(r.height-H*scale)/2;moveTarget={x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale};if(state.dialogOpen)closeModal()});
function tick(now){const dt=Math.min(50,now-lastFrame||16);lastFrame=now;if(state.started&&!state.dialogOpen){let dx=0,dy=0;if(KK['w']||KK['arrowup'])dy--;if(KK['s']||KK['arrowdown'])dy++;if(KK['a']||KK['arrowleft'])dx--;if(KK['d']||KK['arrowright'])dx++;if(dx||dy){const l=Math.hypot(dx,dy);state.x+=dx/l*2.55;state.y+=dy/l*2.55;moveTarget=null}else if(moveTarget){const d=Math.hypot(moveTarget.x-state.x,moveTarget.y-state.y);if(d<5)moveTarget=null;else{state.x+=(moveTarget.x-state.x)/d*2.3;state.y+=(moveTarget.y-state.y)/d*2.3}}state.x=Math.max(22,Math.min(W-22,state.x));state.y=Math.max(62,Math.min(H-24,state.y));state.minute+=dt*.0035;while(state.minute>=60){state.minute-=60;state.hour++;if(state.hour>=24){state.hour=0;state.day++;state.hunger=Math.max(0,state.hunger-6);dailyUpkeep()}state.hunger=Math.max(0,state.hunger-.18);state.energy=Math.max(0,state.energy-.13);if(state.hunger<=0)state.health=Math.max(0,state.health-.8)}if(state.energy<=0)state.health=Math.max(0,state.health-.4);if(state.health<=0){state.health=35;state.energy=40;state.hunger=30;state.day++;state.hour=8;toast('You collapsed. Someone carried you home.');log('You pushed too hard and woke up back at the cottage.')}if(state.crimeUntil&&Date.now()>state.crimeUntil){state.crimeUntil=0;log('The heat from your last crime has cooled.')}setNearby();for(const p of people){if(p.route){const t=(now/1000+p.x*.01)%p.route.length;p.x+=(p.route[Math.floor(t)][0]-p.x)*.004;p.y+=(p.route[Math.floor(t)][1]-p.y)*.004}}if(Math.floor(now/500)!==state.lastUI){state.lastUI=Math.floor(now/500);renderUI()}if(Math.floor(now/900)!==state.lastClock){state.lastClock=Math.floor(now/900);document.getElementById('clock').textContent=`Day ${state.day} · ${String(state.hour).padStart(2,'0')}:${String(Math.floor(state.minute)).padStart(2,'0')}`}}
drawWorld();requestAnimationFrame(tick)}
function dailyUpkeep(){if(state.business){state.coins+=6;log('Your little shop earned 6 coins overnight.')}if(state.spouse){state.coins+=4;log('Your family brought in 4 coins from their work.')}if(state.pet){state.petHappiness=(state.petHappiness||70)-2;log('Your dog waited by the door. It misses you when you are gone too long.')}}
state.attire='Traveler’s clothes';state.petLevel=1;state.petHappiness=70;state.spouse=null;state.business=false;state.lastUI=0;state.lastClock=0;renderUI();requestAnimationFrame(tick);
