ctx.strokeStyle='#6a5234';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(85,570);ctx.lineTo(85,535);ctx.moveTo(75,545);ctx.lineTo(96,545);ctx.stroke();ctx.fillStyle='#b79d67';ctx.beginPath();ctx.arc(85,530,7,0,6.3);ctx.fill();ctx.fillStyle='#4e402c';ctx.beginPath();ctx.moveTo(74,527);ctx.lineTo(96,527);ctx.lineTo(91,522);ctx.lineTo(79,522);ctx.fill();ctx.fillStyle='#8d5c45';ctx.fillRect(77,536,16,13);
'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
print('ok')
