.block-ui{position:absolute;z-index:6;inset:0;display:grid;place-items:center;pointer-events:none}
.block-ring{position:absolute;width:150px;height:150px;border-radius:50%;border:3px solid #e8ce89;animation:blockRing .95s linear forwards}
@keyframes blockRing{from{transform:scale(2.2);opacity:0}18%{opacity:1}to{transform:scale(.55);opacity:.2}}
