  if (state.h > 0 || state.vy > 0) {
    state.vy -= 18 * dt;
    state.h += state.vy * dt;
    if (state.h <= 0) {
      const drop = Math.max(0, state.fallStart || 0);
      state.h = 0; state.vy = 0;
      if (drop > 2.1) {
        const dmg = Math.round((drop - 2.1) * 7);
