    return `<div class="rel-row"><span>${escapeHtml(p.name)}</span><div class="rbar"><i style="width:${pct}%"></i></div><span>${r.bond > 0 ? '+' : ''}${Math.round(r.bond)}</span></div>`;
  }).join('') || '<p class="note-line">You haven’t met anyone properly yet.</p>';
  openModal(`
